    for H, W, grid, n, ops in inputs:
        for i in range(H):
            for j in range(W):
                if grid[i][j] in '0123456789':
                    grid[i][j] = int(grid[i][j])
                elif grid[i][j] in '+-*/':
                    grid[i][j] = grid[i][j]
                else:
                    grid[i][j] = None

        result = []
        for op in ops:
            if op in '0123456789':
                result.append(int(op))
            elif op in '+-*/':
